package com.ruoyi.framework.audit;
import java.util.*;import java.nio.file.*;import java.time.*;import com.alibaba.fastjson2.JSON;import org.springframework.stereotype.Component;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.support.*;import org.springframework.transaction.PlatformTransactionManager;import com.ruoyi.common.utils.SecurityUtils;
@Component public class AuditRecorder {
 public final JdbcTemplate jdbc;private final TransactionTemplate independent;
 public AuditRecorder(JdbcTemplate jdbc,PlatformTransactionManager manager){this.jdbc=jdbc;independent=new TransactionTemplate(manager);independent.setPropagationBehavior(3);}
 public void actor(AuditContext c){try{var u=SecurityUtils.getLoginUser();c.actorId=u.getUserId();c.actor=u.getUsername();c.actorName=u.getUser().getNickName();var rows=jdbc.queryForList("SELECT factory_id FROM sys_user WHERE user_id=?",c.actorId);if(!rows.isEmpty()&&rows.get(0).get("factory_id")!=null)c.actorFactory=((Number)rows.get(0).get("factory_id")).longValue();}catch(Exception ignored){}}
 private String table(AuditContext c){String path=c.path;if(path.equals("/metal/inventory/opening"))return "metal_warehouse_order";if((path.startsWith("/metal/product/")||path.equals("/metal/product")))return "metal_product";if(path.startsWith("/metal/material"))return "metal_material";if(path.startsWith("/metal/process/" )||path.equals("/metal/process"))return "metal_process";if(path.startsWith("/metal/quote-rule"))return "metal_quote_rule";if(path.startsWith("/metal/work-order"))return "metal_work_order";if(path.startsWith("/metal/warehouse-order"))return "metal_warehouse_order";if(path.startsWith("/metal/inventory"))return "metal_inventory";if(path.startsWith("/metal/process-batch"))return "metal_process_batch";if(path.startsWith("/metal/warning-record"))return "metal_warning_record";if(path.startsWith("/metal/warehouse/" )||path.equals("/metal/warehouse"))return "metal_warehouse";if(path.startsWith("/metal/factory"))return "metal_factory";if(path.startsWith("/metal/production-line"))return "metal_production_line";if(path.equals("/metal/quotation/save")||path.startsWith("/metal/quotation/orders"))return "metal_saved_quotation";if(path.startsWith("/system/user"))return "sys_user";if(path.startsWith("/system/role"))return "sys_role";return null;}
 private String pk(String table){return switch(table){case "metal_product"->"product_id";case "metal_material"->"material_id";case "metal_process"->"process_id";case "metal_quote_rule"->"rule_id";case "metal_work_order"->"work_order_id";case "metal_warehouse_order"->"order_id";case "metal_saved_quotation"->"quote_id";case "metal_inventory"->"inventory_id";case "metal_process_batch"->"batch_id";case "metal_warning_record"->"warning_id";case "metal_warehouse"->"warehouse_id";case "metal_factory"->"factory_id";case "metal_production_line"->"production_line_id";case "sys_user"->"user_id";case "sys_role"->"role_id";default->"id";};}
 public Map<String,Object> snapshot(AuditContext c,Object body,Object result){String table=table(c);if(table==null)return Map.of();c.objectType=table;if(result!=null&&body instanceof com.ruoyi.metal.service.WarehouseImportService.Input input)c.factories.add(input.factoryId());Set<Long> ids=new TreeSet<>();if(c.path.startsWith("/system/user/profile"))ids.add(SecurityUtils.getUserId());String[] paths=c.path.split("/");for(String part:paths)if(part.matches("[0-9]+(,[0-9]+)*"))for(String id:part.split(","))if(ids.size()<100)ids.add(Long.valueOf(id));try{var json=JSON.parseObject(JSON.toJSONString(body));for(String key:List.of("id","factoryId","factoryIds")){if(key.equals("factoryId")&&!table.equals("metal_factory"))continue;if(json.get(key)!=null&&json.get(key).toString().matches("[0-9]+"))ids.add(Long.valueOf(json.get(key).toString()));}if(json.get("requestId")!=null&&Set.of("metal_work_order","metal_warehouse_order","metal_process_batch","metal_saved_quotation").contains(table)){var rows=jdbc.queryForList("SELECT "+pk(table)+" id FROM "+table+" WHERE request_id=?",json.get("requestId"));rows.forEach(r->ids.add(((Number)r.get("id")).longValue()));if(result==null&&!rows.isEmpty())c.replayed=true;}}catch(Exception ignored){}if(!table.equals("metal_inventory")&&result instanceof String s&&s.matches("[0-9]+"))ids.add(Long.valueOf(s));if(table.equals("metal_saved_quotation")&&result instanceof Map<?,?> values&&values.get("id")!=null&&values.get("id").toString().matches("[0-9]+"))ids.add(Long.valueOf(values.get("id").toString()));if(table.equals("metal_quote_rule"))ids.add(1L);Map<String,Object> out=new LinkedHashMap<>();for(Long id:ids){var rows=jdbc.queryForList("SELECT * FROM "+table+" WHERE "+pk(table)+"=?",id);if(!rows.isEmpty()){var row=rows.get(0);Object f=table.equals("metal_factory")?id:row.get("factory_id");if(f instanceof Number n)c.factories.add(n.longValue());Object code=row.getOrDefault("order_no",row.getOrDefault("batch_no",row.getOrDefault("quote_no",id)));c.businessCode=code.toString();if(table.equals("metal_product"))row.put("processes",jdbc.queryForList("SELECT * FROM metal_product_process WHERE product_id=? ORDER BY sequence_no LIMIT 100",id));if(table.equals("metal_factory"))row.put("lines",jdbc.queryForList("SELECT production_line_id,production_line_name,factory_id FROM metal_production_line WHERE factory_id=? ORDER BY production_line_id LIMIT 100",id));if(table.equals("metal_production_line"))row.put("products",jdbc.queryForList("SELECT product_id FROM metal_line_product WHERE production_line_id=? ORDER BY product_id LIMIT 100",id));if(table.equals("metal_work_order")){row.put("items",jdbc.queryForList("SELECT * FROM metal_work_order_item WHERE work_order_id=? ORDER BY item_id LIMIT 100",id));row.put("steps",jdbc.queryForList("SELECT s.* FROM metal_work_order_step s JOIN metal_work_order_item i ON i.item_id=s.item_id WHERE i.work_order_id=? ORDER BY s.item_id,s.sequence_no LIMIT 100",id));}if(table.equals("metal_warehouse_order"))row.put("lines",jdbc.queryForList("SELECT * FROM metal_warehouse_order_line WHERE order_id=? ORDER BY line_id LIMIT 100",id));if(table.equals("metal_inventory")&&c.path.matches("/metal/inventory/[0-9]+/adjust")&&result instanceof String saved&&saved.matches("[0-9]+")){var documents=jdbc.queryForList("SELECT * FROM metal_warehouse_order WHERE order_id=? AND factory_id=? AND type='ADJUST'",Long.valueOf(saved),f);if(!documents.isEmpty()){var document=documents.get(0);c.businessCode=document.get("order_no").toString();row.put("adjustmentOrder",document);}}out.put(id.toString(),AuditRedactor.redact(row));}}return out;}
 public void success(AuditContext c,Object after){
  var data=event(c,"SUCCESS","",after);String payload=JSON.toJSONString(data);
  jdbc.update("INSERT INTO audit_outbox(event_id,event_json) VALUES(?,?)",c.event,payload);c.logged=true;
  if(TransactionSynchronizationManager.isSynchronizationActive())TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){
   @Override public void afterCompletion(int status){
    if(status==STATUS_COMMITTED)return;
    c.logged=false;c.failureCode="SYSTEM_ERROR";
    var failed=new LinkedHashMap<String,Object>(data);failed.put("code","SYSTEM_ERROR");
    failed.put("error",status==STATUS_ROLLED_BACK?"事务最终回滚":"事务提交结果未知，需按事件ID核对");
    failed.put("response","");failed.put("changes",Map.of("before",c.before,"after",Map.of()));
    c.logged=persistFailure(failed);
   }
  });
 }
 private boolean persistFailure(Map<String,Object> event){try{independent.executeWithoutResult(t->jdbc.update("INSERT IGNORE INTO audit_outbox(event_id,event_json) VALUES(?,?)",event.get("event"),JSON.toJSONString(event)));return true;}catch(Exception unavailable){fallback(event);return false;}}

 public Map<String,Object> event(AuditContext c,String code,String error,Object after){Map<String,Object> e=new LinkedHashMap<>();e.put("event",c.event);e.put("trace",c.trace);e.put("actorId",c.actorId);e.put("actorFactory",c.actorFactory);e.put("actor",AuditRedactor.text(c.actor));e.put("actorName",AuditRedactor.text(c.actorName));if(c.actorFactory!=null&&c.actorId!=null&&c.actorId!=1&&!c.factories.isEmpty()&&!c.factories.contains(c.actorFactory))c.factories.add(c.actorFactory);if(c.factories.size()==1)c.businessFactory=c.factories.iterator().next();else if(c.factories.isEmpty()&&c.actorId!=null&&c.actorId!=1)c.businessFactory=c.actorFactory;e.put("factory",c.businessFactory);if(c.businessFactory!=null){var names=jdbc.queryForList("SELECT factory_name FROM metal_factory WHERE factory_id=?",c.businessFactory);if(!names.isEmpty())e.put("factoryName",names.get(0).get("factory_name"));}e.put("factories",c.factories);e.put("title",c.title);e.put("action",c.action);e.put("path",c.path);e.put("verb",c.verb);e.put("code",code);e.put("error",AuditRedactor.text(error));e.put("businessCode",c.businessCode);e.put("objectType",c.objectType);e.put("objects",Map.of("type",c.objectType,"businessCode",c.businessCode));e.put("request",c.request);e.put("response",c.result);e.put("replayed",c.replayed);e.put("cost",System.currentTimeMillis()-c.started);e.put("time",LocalDateTime.now(ZoneId.of("Asia/Shanghai")).toString());e.put("changes",Map.of("before",c.before,"after",after==null?Map.of():after));return e;}
 public void failure(AuditContext c,String code,String message){if(c.logged)return;c.logged=persistFailure(event(c,code,message,null));}
 public static synchronized void fallback(Map<String,Object> event){try{Files.createDirectories(Path.of("logs"));Files.writeString(Path.of("logs/audit-fallback.jsonl"),JSON.toJSONString(event)+System.lineSeparator(),StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(Exception ignored){}}
}
